// Permanent erase is the GDPR route, not the tidy-up button — hence the
// password and the typed confirmation naming the lead.
window.ldErase = function (id) {
  var l = lead(id); if (!l) return;
  var name = l.full_name || 'this lead';
  if (!confirm('Permanently erase "' + name + '"?\n\nName, email, phone, the Meta payload and the property details are wiped. ' +
               'A tombstone row stays so the funnel counts and the erasure itself remain provable.\n\nThis cannot be undone.')) return;
  var pw = prompt('Enter the password to confirm the erasure:');
  if (pw === null) return;
  jsend('/api/leads/' + id, 'DELETE', { password: String(pw).trim(), by: who() }).then(function (r) {
    if (!r.ok) { toast((r.j && r.j.error) || 'Not erased.', 'err'); return; }
    openId = null; sheet = null; toast('Erased. The tombstone stays.'); reload();
  });
};

