// Permanent erase — simple yes/no. Tombstone row stays for funnel counts.
window.ldErase = function (id) {
  var l = lead(id); if (!l) return;
  var name = (typeof prettyPerson === 'function' ? prettyPerson(l.full_name) : '') || l.full_name || 'this lead';
  if (!confirm('Delete "' + name + '" permanently?\n\nThis cannot be undone.')) return;
  jsend('/api/leads/' + id, 'DELETE', { by: who() }).then(function (r) {
    if (!r.ok) { toast((r.j && r.j.error) || 'Not erased.', 'err'); return; }
    openId = null; sheet = null; toast('Deleted.'); reload();
  });
};
